const PAGE = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n  <title>栖境 AI 家居空间预览</title>\n  <meta name=\"description\" content=\"以房间照片为主编辑画布，通过空间理解、参考图引导、场景编辑与质量检查生成真实家具预览。\" />\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='9' fill='%231b4d42'/%3E%3Cpath d='M7 16.5 16 9l9 7.5v8H7z' fill='%23fff'/%3E%3Cpath d='M12 24v-7h8v7' fill='%23de7d42'/%3E%3C/svg%3E\" />\n  <style>\n    :root{--ink:#17211e;--muted:#6b7671;--line:#dde3df;--paper:#f3f4f1;--panel:#fff;--brand:#1b4d42;--brand2:#286e5d;--accent:#d8783e;--accentSoft:#fff0e6;--soft:#edf3f0;--danger:#b64d46;--shadow:0 16px 42px rgba(20,39,32,.10);font-family:Inter,\"PingFang SC\",\"Microsoft YaHei\",system-ui,sans-serif;color:var(--ink);background:var(--paper)}\n    *{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden}button,input,textarea{font:inherit}button{color:inherit}.hidden{display:none!important}.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n    .app{height:100vh;display:grid;grid-template-rows:62px minmax(0,1fr)}\n    .topbar{display:flex;align-items:center;justify-content:space-between;padding:0 20px;background:#fafbf8;border-bottom:1px solid var(--line);z-index:20}.brand{display:flex;align-items:center;gap:10px;min-width:230px}.brandmark{width:35px;height:35px;border-radius:11px;display:grid;place-items:center;background:var(--brand);color:#fff;font-weight:800}.brandname{font-weight:780;font-size:17px}.brandsub{font-size:11px;color:var(--muted);margin-top:2px}.viewnav{display:flex;gap:4px;background:#e9ece8;padding:4px;border-radius:12px}.viewbtn{border:0;background:transparent;padding:8px 16px;border-radius:9px;color:#65706b;cursor:pointer}.viewbtn.active{background:#fff;color:var(--ink);font-weight:750;box-shadow:0 2px 8px rgba(0,0,0,.07)}.topright{display:flex;align-items:center;justify-content:flex-end;gap:9px;min-width:230px}.adminshortcut,.avatar{width:36px;height:36px;border-radius:11px;display:grid;place-items:center}.adminshortcut{border:1px solid var(--line);background:#fff;cursor:pointer}.avatar{background:#dfc2a7;font-size:12px;font-weight:800}\n    .workspace{min-height:0;display:grid;grid-template-columns:260px minmax(520px,1fr) 310px}.workspace.off,.admin.off{display:none}\n    .sessions{min-height:0;overflow:auto;background:#f7f8f5;border-right:1px solid var(--line);padding:15px 12px}.sessions-head{display:flex;align-items:center;justify-content:space-between;padding:2px 4px 12px}.sessions-head strong{font-size:14px}.newchat{border:0;background:var(--brand);color:#fff;border-radius:9px;padding:7px 10px;font-size:12px;font-weight:720;cursor:pointer}.searchbox{width:100%;border:1px solid #dfe4e1;background:#fff;border-radius:10px;padding:9px 11px;outline:0;margin-bottom:12px}.session{width:100%;border:0;background:transparent;border-radius:12px;padding:11px;text-align:left;cursor:pointer;margin:3px 0}.session:hover{background:#eef2ef}.session.active{background:#e3eee9}.session-title{font-size:13px;font-weight:720;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.session-meta{display:flex;justify-content:space-between;margin-top:5px;font-size:11px;color:#85908b}.session-badge{color:var(--accent);font-weight:750}.sessions-note{margin:18px 8px;color:#8a9490;font-size:11px;line-height:1.6}\n    .chat{min-width:0;min-height:0;display:grid;grid-template-rows:61px minmax(0,1fr) auto;background:#eef0ed}.chathead{display:flex;align-items:center;justify-content:space-between;padding:0 20px;background:#fff;border-bottom:1px solid var(--line)}.chathead-title{font-size:16px;font-weight:770}.chathead-meta{font-size:11px;color:var(--muted);margin-top:3px}.chathead-actions{display:flex;gap:7px}.smallbtn{border:1px solid var(--line);background:#fff;border-radius:9px;padding:8px 10px;font-size:12px;cursor:pointer}.mobile-new{display:none}\n    .feed{overflow:auto;padding:22px 20px 28px;scroll-behavior:smooth}.feed-inner{max-width:760px;margin:0 auto}.dayline{text-align:center;color:#929b97;font-size:11px;margin:2px 0 18px}.message{display:flex;gap:9px;margin:16px 0;align-items:flex-start}.message.user{justify-content:flex-end}.msgavatar{flex:0 0 30px;height:30px;border-radius:9px;display:grid;place-items:center;background:var(--brand);color:#fff;font-size:11px;font-weight:800}.message.user .msgavatar{order:2;background:#dec3ab;color:#4c3423}.bubble{max-width:78%;padding:10px 12px;border-radius:4px 13px 13px 13px;background:#fff;box-shadow:0 4px 14px rgba(20,40,32,.05);font-size:14px;line-height:1.55}.message.user .bubble{border-radius:13px 4px 13px 13px;background:var(--accentSoft);color:#5e402e}.bubble.system{color:#64706b}.quote-inline{display:flex;align-items:center;gap:8px;margin-bottom:8px;padding:7px;border-left:3px solid var(--accent);background:rgba(255,255,255,.66);border-radius:6px}.quote-inline img{width:45px;height:35px;border-radius:6px;object-fit:cover}.quote-inline strong{display:block;font-size:11px}.quote-inline span{font-size:10px;color:#82644f}\n    .asset-message{margin:14px 39px;max-width:640px}.asset-kicker{font-size:11px;color:#7c8782;margin:0 0 7px}.image-card{position:relative;border-radius:16px;overflow:hidden;background:#18231f;box-shadow:var(--shadow)}.image-stage{position:relative;aspect-ratio:16/9;overflow:hidden;cursor:crosshair}.image-stage .room{width:100%;height:100%;object-fit:cover;display:block}.point{position:absolute;left:20%;top:67%;width:24px;height:24px;border:3px solid #fff;border-radius:50%;background:var(--accent);box-shadow:0 3px 14px rgba(0,0,0,.4);transform:translate(-50%,-50%);z-index:5}.point:after{content:\"落点\";position:absolute;left:19px;top:-5px;padding:4px 7px;border-radius:6px;background:#fff;color:var(--ink);font-size:10px;font-weight:750;white-space:nowrap}.image-caption{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 11px;background:#fff}.image-caption-text strong{font-size:12px}.image-caption-text span{display:block;font-size:10px;color:var(--muted);margin-top:2px}.image-actions{display:flex;gap:6px}.image-action{border:1px solid var(--line);background:#fff;border-radius:8px;padding:6px 8px;font-size:11px;cursor:pointer}.image-action.primary{border-color:#c6d8d1;color:var(--brand);font-weight:750}.round-status{display:grid;gap:7px;margin:10px 39px;padding:11px 12px;background:#fff;border:1px solid #e0e5e2;border-radius:12px}.round-row{display:flex;align-items:center;gap:9px;font-size:11px;color:#69746f}.round-dot{width:7px;height:7px;border-radius:50%;background:#b8c1bd}.round-row.done .round-dot{background:#2b7c62}.round-row.running .round-dot{background:var(--accent);box-shadow:0 0 0 4px #f9e7db}.round-row.failed .round-dot{background:var(--danger)}.round-row strong{color:#3f4a46}.typing{display:inline-flex;gap:4px}.typing i{width:5px;height:5px;border-radius:50%;background:#86918c;animation:bounce 1s infinite}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}@keyframes bounce{0%,60%,100%{transform:none}30%{transform:translateY(-4px)}}\n    .composer-wrap{border-top:1px solid var(--line);background:#fff;padding:10px 18px 14px}.composer-inner{max-width:760px;margin:0 auto}.replybar{display:none;align-items:center;gap:9px;padding:7px 9px;margin-bottom:7px;border:1px solid #e6c7b1;background:#fff6ef;border-radius:10px}.replybar.show{display:flex}.replybar img{width:44px;height:34px;border-radius:6px;object-fit:cover}.replytext{min-width:0;flex:1}.replytext strong{display:block;font-size:11px}.replytext span{display:block;font-size:10px;color:#8b674e;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.replyclose{border:0;background:transparent;font-size:18px;cursor:pointer}.composer{border:1px solid #ccd5d0;border-radius:14px;padding:9px;background:#fff;box-shadow:0 8px 24px rgba(20,40,32,.07)}.composer textarea{display:block;width:100%;height:48px;border:0;resize:none;outline:0;line-height:1.45}.composerbar{display:flex;align-items:center;justify-content:space-between;gap:8px}.composer-left{display:flex;gap:6px;align-items:center}.toolpill{border:1px solid var(--line);background:#f8faf8;border-radius:8px;padding:6px 8px;font-size:11px;cursor:pointer}.toolpill.active{background:#e6f0ec;border-color:#c8dcd4;color:var(--brand);font-weight:750}.targettext{font-size:10px;color:var(--muted)}.send{border:0;border-radius:9px;padding:8px 14px;background:var(--accent);color:#fff;font-weight:760;cursor:pointer}.send:disabled{opacity:.55;cursor:wait}\n    .context{min-height:0;overflow:auto;background:#fff;border-left:1px solid var(--line);padding:16px}.context h2{font-size:14px;margin:0 0 13px}.upload-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.upload-tile{position:relative;border:1px dashed #cbd4cf;background:#fafbfa;border-radius:11px;padding:7px;cursor:pointer;min-height:126px}.upload-tile img{width:100%;height:76px;object-fit:cover;border-radius:7px}.upload-tile.product img{object-fit:contain;background:repeating-conic-gradient(#f1f1ee 0 25%,#fff 0 50%) 50%/12px 12px}.upload-tile strong{display:block;font-size:11px;margin-top:6px}.upload-tile span{font-size:9px;color:var(--muted)}.upload-tile.empty{display:flex;flex-direction:column;justify-content:flex-end;background:linear-gradient(145deg,#fafbfa,#eef2ef)}.upload-tile.empty:before{content:\"＋\";position:absolute;inset:18px 0 auto;text-align:center;color:#9aa49f;font-size:26px}.upload-tile.empty img{display:none}.upload-tile.processing:after{content:\"正在识别主体…\";position:absolute;inset:7px 7px auto;padding:28px 4px;background:rgba(27,77,66,.88);border-radius:7px;color:#fff;text-align:center;font-size:10px;font-weight:750}.product-status{margin-top:8px;padding:8px 9px;border-radius:8px;background:#f1f5f3;color:#587069;font-size:10px;line-height:1.45}.product-status.ok{background:#e8f4ee;color:#286451}.product-status.error{background:#fff0ea;color:#9a4d2e}.context-section{padding:15px 0;border-top:1px solid #e7ebe8;margin-top:15px}.operation{display:grid;grid-template-columns:1fr 1fr;gap:5px;padding:4px;background:#edf0ed;border-radius:11px}.opbtn{border:0;border-radius:8px;padding:8px;background:transparent;font-size:11px;cursor:pointer}.opbtn.active{background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.07);font-weight:750}.size-row{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:10px}.size-field{position:relative}.size-field label{display:block;margin:0 0 4px;font-size:9px;color:#73807a}.size-field input{min-width:0;width:100%;border:1px solid var(--line);border-radius:8px;padding:8px 24px 8px 8px;font-size:11px}.size-field:after{content:\"cm\";position:absolute;right:7px;bottom:9px;font-size:9px;color:#8b9591}.scale-hint{margin-top:7px;color:#5b6d66;font-size:10px;line-height:1.4}.target-card{margin-top:10px;padding:10px;border-radius:10px;background:#edf5f1;color:#356154;font-size:11px;line-height:1.5}.context-tip{font-size:10px;color:#89938f;line-height:1.55;margin-top:9px}\n    .admin{min-height:0;overflow:auto;padding:22px;background:#f2f4f2}.admin-inner{max-width:1260px;margin:0 auto}.admin-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:16px}.admin-head h1{font-size:24px;margin:0}.admin-head p{font-size:12px;color:var(--muted);margin:5px 0 0}.tasks{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden}.task{display:grid;grid-template-columns:1.2fr 1fr .7fr 1fr .8fr auto;gap:8px;align-items:center;padding:12px 14px;border-top:1px solid #edf0ee;font-size:12px}.task:first-child{border-top:0}.task-head{background:#f8faf8;color:#7a8580;font-size:10px;font-weight:700}.latest{font-style:normal;font-size:9px;color:#fff;background:#dc7135;border-radius:99px;padding:3px 6px;margin-right:5px}.status{display:inline-flex;width:max-content;padding:4px 7px;border-radius:99px;background:#e5f2ec;color:#276a55;font-size:10px;font-weight:750}.view-flow{border:1px solid #c9d9d2;background:#fff;color:var(--brand);border-radius:8px;padding:6px 8px;font-size:10px;font-weight:750;cursor:pointer}.pipeline{margin-top:18px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:17px}.pipeline-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:14px}.pipeline-head h2{font-size:18px;margin:0}.pipeline-head p{font-size:11px;color:var(--muted);margin:4px 0 0}.pipeline-summary{display:flex;gap:7px;flex-wrap:wrap}.summary-pill{padding:6px 8px;border-radius:8px;background:#eef3f0;font-size:10px}.round-grid{display:grid;grid-template-columns:repeat(3,minmax(260px,1fr));gap:12px}.round-card{min-width:0;border:1px solid #dfe5e1;border-radius:12px;overflow:hidden;background:#fafbfa}.round-card-head{display:flex;align-items:center;justify-content:space-between;padding:10px 11px}.round-name{font-size:12px;font-weight:800}.round-state{font-size:9px;color:#27725a}.round-visual{position:relative;aspect-ratio:4/3;background:#e7e5df;overflow:hidden}.round-image-wrap{position:relative;width:100%;height:100%}.round-visual .round-room{width:100%;height:100%;object-fit:cover}.round-download{position:absolute;right:8px;bottom:8px;padding:6px 8px;border-radius:7px;background:rgba(18,35,29,.86);color:#fff;text-decoration:none;font-size:9px;font-weight:750}.jsonbox{height:100%;padding:11px;background:#17231f;color:#dbe7e1;font:9px/1.55 ui-monospace,monospace;white-space:pre-wrap;overflow:auto}.round-body{padding:10px}.round-body p{font-size:10px;color:#69746f;line-height:1.45;margin:0 0 7px}.round-body .request-id{overflow-wrap:anywhere;color:#3d6557}.round-body details summary{font-size:10px;color:var(--brand);font-weight:750;cursor:pointer}.round-body pre{max-height:260px;overflow:auto;white-space:pre-wrap;font:9px/1.5 ui-monospace,monospace;color:#606b66}.io-strip{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:7px}.io{font-size:8px;color:#7d8782}.io strong{display:block;color:#394540;font-size:9px;margin-top:2px}\n    .toast{position:fixed;left:50%;bottom:24px;z-index:99;transform:translate(-50%,20px);opacity:0;padding:10px 15px;border-radius:10px;background:#17231f;color:#fff;font-size:12px;transition:.22s}.toast.show{transform:translate(-50%,0);opacity:1}\n    @media(max-width:1040px){.workspace{grid-template-columns:220px minmax(480px,1fr) 270px}.brand,.topright{min-width:auto}.round-grid{grid-template-columns:repeat(2,minmax(260px,1fr))}.action-label{display:none}}\n    @media(max-width:800px){html,body{overflow:auto}.app{min-height:100vh;height:auto;grid-template-rows:58px auto}.topbar{position:sticky;top:0;height:58px}.brandsub,.viewnav{display:none}.workspace{display:block;min-height:calc(100vh - 58px)}.sessions,.context{display:none}.chat{min-height:calc(100vh - 58px);grid-template-rows:57px minmax(60vh,1fr) auto}.feed{padding:16px 10px}.asset-message,.round-status{margin-left:8px;margin-right:8px}.bubble{max-width:88%}.composer-wrap{position:sticky;bottom:0;padding:8px}.admin{padding:12px}.task{grid-template-columns:1.2fr .8fr .8fr auto}.task>*:nth-child(2),.task>*:nth-child(4){display:none}.round-grid{grid-template-columns:1fr}.pipeline-head{display:block}.mobile-new{display:inline-flex}.chathead-actions #openContext{display:none}.topright .avatar{display:none}}\n  </style>\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"topbar\">\n    <div class=\"brand\"><div class=\"brandmark\">栖</div><div><div class=\"brandname\">栖境 AI</div><div class=\"brandsub\">在对话中预览真实空间</div></div></div>\n    <nav class=\"viewnav\"><button class=\"viewbtn active\" data-view=\"workspace\">对话生图</button><button class=\"viewbtn\" data-view=\"admin\">管理员后台</button></nav>\n    <div class=\"topright\"><button class=\"adminshortcut\" id=\"adminShortcut\" aria-label=\"管理员后台\">⚙</button><div class=\"avatar\">ND</div></div>\n  </header>\n\n  <main class=\"workspace\" id=\"workspace\">\n    <aside class=\"sessions\">\n      <div class=\"sessions-head\"><strong>生图对话</strong><button class=\"newchat\" id=\"newChat\">＋ 新对话</button></div>\n      <input class=\"searchbox\" id=\"sessionSearch\" placeholder=\"搜索生图题目\" />\n      <button class=\"session active\" data-chat=\"chat-chair\"><div class=\"session-title\">把焦糖色单椅放到窗边</div><div class=\"session-meta\"><span>刚刚</span><span class=\"session-badge\">待生成</span></div></button>\n      <button class=\"session\" data-chat=\"chat-lamp\"><div class=\"session-title\">桌面加一盏小台灯</div><div class=\"session-meta\"><span>10:26</span><span>3 张图</span></div></button>\n      <button class=\"session\" data-chat=\"chat-cabinet\"><div class=\"session-title\">替换入口处的收纳柜</div><div class=\"session-meta\"><span>昨天</span><span>2 张图</span></div></button>\n      <button class=\"session\" data-chat=\"chat-vase\"><div class=\"session-title\">书架空位加一个陶瓷花瓶</div><div class=\"session-meta\"><span>周六</span><span>4 张图</span></div></button>\n      <button class=\"session\" data-chat=\"chat-folding\"><div class=\"session-title\">阳台角落放一张折叠椅</div><div class=\"session-meta\"><span>周五</span><span>1 张图</span></div></button>\n      <div class=\"sessions-note\">每一项是一段独立对话。标题来自首条生图指令，不限制照片必须是某种房间。</div>\n    </aside>\n\n    <section class=\"chat\">\n      <div class=\"chathead\"><div><div class=\"chathead-title\">把焦糖色单椅放到窗边</div><div class=\"chathead-meta\">场景编辑模式 · 房间图为主编辑画布</div></div><div class=\"chathead-actions\"><button class=\"smallbtn mobile-new\" id=\"mobileNewChat\">＋ 新对话</button><button class=\"smallbtn\" id=\"openContext\">本轮素材</button><button class=\"smallbtn\" id=\"clearPoint\">清除点选</button></div></div>\n      <div class=\"feed\" id=\"feed\"><div class=\"feed-inner\" id=\"feedInner\">\n        <div class=\"dayline\">今天 11:42</div>\n        <div class=\"asset-message\"><div class=\"asset-kicker\">本轮输入</div><div class=\"image-card\"><div class=\"image-stage selectable-image\" data-version=\"Original\"><img class=\"room\" src=\"assets/living-room.png\" alt=\"用户上传的空间照片\" /><span class=\"point\" id=\"targetPoint\"></span></div><div class=\"image-caption\"><div class=\"image-caption-text\"><strong>原始照片</strong><span>单击图片选择摆放位置</span></div><div class=\"image-actions\"><button class=\"image-action quote-btn\" data-version=\"Original\">引用</button></div></div></div></div>\n        <div class=\"message\"><div class=\"msgavatar\">AI</div><div class=\"bubble system\">已切换到场景理解式编辑：空间照片是主编辑画布，商品图只作为外观参考。点选物体底部中心并输入要求后，系统会先分析地面、透视和光线，再生成融合图并执行视觉质检。</div></div>\n      </div></div>\n\n      <div class=\"composer-wrap\"><div class=\"composer-inner\">\n        <div class=\"replybar\" id=\"replyBar\"><img src=\"assets/living-room.png\" alt=\"被引用效果图\" /><div class=\"replytext\"><strong id=\"replyTitle\">正在引用效果图 V1</strong><span>本轮将严格以该图为基础，不自动使用最新图</span></div><button class=\"replyclose\" id=\"replyClose\" aria-label=\"取消引用\">×</button></div>\n        <div class=\"composer\"><textarea id=\"prompt\" placeholder=\"继续描述调整，例如：椅子再小一点，向右移动一些\"></textarea><div class=\"composerbar\"><div class=\"composer-left\"><button class=\"toolpill active op\" data-op=\"ADD\">添加</button><button class=\"toolpill op\" data-op=\"REPLACE\">替换</button><button class=\"toolpill\" id=\"attachProduct\">商品图</button><span class=\"targettext\" id=\"targetText\">点选位置 20%, 67%</span></div><button class=\"send\" id=\"send\">发送并生成</button></div></div>\n      </div></div>\n    </section>\n\n    <aside class=\"context\" id=\"context\">\n      <h2>本轮素材</h2>\n      <div class=\"upload-grid\"><label class=\"upload-tile\" id=\"spaceTile\"><img id=\"spaceThumb\" src=\"assets/living-room.png\" alt=\"空间原图\" /><strong>空间原图</strong><span>点击更换任意照片</span><input class=\"sr\" id=\"spaceInput\" type=\"file\" accept=\"image/png,image/jpeg\" /></label><label class=\"upload-tile product\" id=\"productTile\"><img id=\"productThumb\" src=\"assets/caramel-chair.png\" alt=\"已提取主体的商品图\" /><strong>商品参考图</strong><span>点击更换商品</span><input class=\"sr\" id=\"productInput\" type=\"file\" accept=\"image/png,image/jpeg\" /></label></div>\n      <div class=\"product-status ok\" id=\"productStatus\">商品原图仅作为外观参考 · 不再直接抠图叠加</div>\n      <div class=\"context-section\"><h2>操作类型</h2><div class=\"operation\"><button class=\"opbtn active\" data-op=\"ADD\">添加到照片</button><button class=\"opbtn\" data-op=\"REPLACE\">替换现有物品</button></div><div class=\"size-row\"><div class=\"size-field\"><label for=\"dimLength\">长度</label><input id=\"dimLength\" inputmode=\"decimal\" aria-label=\"长度（厘米）\" placeholder=\"如 200\" /></div><div class=\"size-field\"><label for=\"dimWidth\">宽度</label><input id=\"dimWidth\" inputmode=\"decimal\" aria-label=\"宽度（厘米）\" placeholder=\"如 80\" /></div><div class=\"size-field\"><label for=\"dimHeight\">高度</label><input id=\"dimHeight\" inputmode=\"decimal\" aria-label=\"高度（厘米）\" placeholder=\"如 80\" /></div></div><div class=\"scale-hint\" id=\"scaleHint\">填写实际尺寸后，将结合点选位置的纵深估算画面比例。</div><div class=\"target-card\" id=\"targetCard\">已点选目标位置<br><strong>X 20% · Y 67%</strong></div><div class=\"context-tip\">点选位置是物体的落地点。实际尺寸会与照片纵深一起计算显示大小；照片可以是房间、桌面、柜面或任意局部空间。</div></div>\n    </aside>\n  </main>\n\n  <section class=\"admin off\" id=\"admin\"><div class=\"admin-inner\">\n    <div class=\"admin-head\"><div><h1>AI 生成任务</h1><p>展示最新任务的真实模型调用、3–4 张后台过程图、各轮 Prompt、耗时与视觉质检结果</p></div><button class=\"smallbtn\" id=\"refresh\">同步最新任务</button></div>\n    <div class=\"tasks\"><div class=\"task task-head\"><span>任务</span><span>对话题目</span><span>操作</span><span>基础图</span><span>状态</span><span>详情</span></div><div id=\"taskRows\"></div></div>\n    <div class=\"pipeline\" id=\"pipeline\"><div class=\"pipeline-head\"><div><h2>尚无真实生成任务</h2><p>发送第一条指令后，这里会显示需求解析、基础生成、几何修正、光影融合、质量检查，以及必要时的第 4 张纠错图。</p></div></div></div>\n  </div></section>\n</div>\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n<script src=\"app.js\"></script>\n</body>\n</html>\n";
const APP_JS = "const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];\nconst workspace=$('#workspace'),admin=$('#admin'),feed=$('#feed'),feedInner=$('#feedInner');\nconst conversations=new Map(),tasks=[],resultImages=new Map();\nconst TASK_STORAGE_KEY='qijing-ai-generation-tasks-v2';\nconst CONVERSATION_STORAGE_KEY='qijing-ai-conversations-v2';\nlet currentChatId='chat-chair',reference=null,target={x:20,y:67},operation='ADD';\nlet productSrc='assets/caramel-chair.png',roomSrc='assets/living-room.png',version=0,toastTimer,taskCounter=25001;\n\nfunction toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}\nfunction escapeHTML(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction switchView(view){workspace.classList.toggle('off',view!=='workspace');admin.classList.toggle('off',view!=='admin');$$('.viewbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#adminShortcut').textContent=view==='admin'?'⌂':'⚙';if(view==='admin'){loadTaskHistory();renderTaskRows();if(tasks[0])renderPipeline(tasks[0])}}\n$$('.viewbtn').forEach(b=>b.onclick=()=>switchView(b.dataset.view));\n$('#adminShortcut').onclick=()=>switchView(admin.classList.contains('off')?'admin':'workspace');\n\nfunction setOperation(op,quiet=false){operation=op;$$('[data-op]').forEach(b=>b.classList.toggle('active',b.dataset.op===op));if(!quiet){snapshotCurrent();toast(op==='ADD'?'添加模式：点选家具底部中心':'替换模式：点选要替换物体的中心或接地点')}}\n$$('[data-op]').forEach(b=>b.onclick=()=>setOperation(b.dataset.op));\nfunction getDimensions(){const read=id=>{const n=parseFloat($(id).value);return Number.isFinite(n)&&n>0?n:null};return{length:read('#dimLength'),width:read('#dimWidth'),height:read('#dimHeight')}}\nfunction updateTargetUI(){if(target){$('#targetText').textContent=`点选位置 ${target.x}%, ${target.y}%`;$('#targetCard').innerHTML=`已点选目标位置<br><strong>X ${target.x}% · Y ${target.y}%</strong>`}else{$('#targetText').textContent='尚未点选位置';$('#targetCard').innerHTML='尚未点选目标位置<br><strong>请直接单击对话中的图片</strong>'}}\nfunction updateScaleHint(){const d=getDimensions();$('#scaleHint').textContent=d.length||d.width||d.height?'已输入真实尺寸；空间分析会把厘米尺寸与地面纵深、透视比例共同送入生成模型。':'未填写时，空间分析会根据家具类别、地面纵深和房间参照物估算合理比例。'}\n['#dimLength','#dimWidth','#dimHeight'].forEach(id=>$(id).addEventListener('input',updateScaleHint));\nfunction setPoint(e){const stage=e.currentTarget,r=stage.getBoundingClientRect();target={x:Math.round((e.clientX-r.left)/r.width*100),y:Math.round((e.clientY-r.top)/r.height*100)};let point=$('.point',stage);if(!point){point=document.createElement('span');point.className='point';stage.appendChild(point)}point.style.left=target.x+'%';point.style.top=target.y+'%';updateTargetUI();toast('落点已记录，将作为空间编辑约束而不是贴图坐标')}\n\nfunction setReference(v){reference=v;const src=resultImages.get(v)||roomSrc;$('#replyTitle').textContent='正在引用效果图 '+v;$('#replyBar img').src=src;$('#replyBar').classList.add('show');$('#prompt').focus();toast('下一轮将以 '+v+' 作为主编辑图像')}\n$('#replyClose').onclick=()=>{reference=null;$('#replyBar').classList.remove('show')};\n$('#clearPoint').onclick=()=>{$$('.point',feedInner).forEach(p=>p.remove());target=null;updateTargetUI();toast('已清除点选位置')};\n\nfunction bindInteractive(root=document){\n  $$('.selectable-image',root).forEach(el=>el.onclick=setPoint);\n  $$('.quote-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();setReference(b.dataset.version)});\n  $$('.regen-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();$('#prompt').value='基于相同素材重新生成，重点修正空间比例、透视、接地与光影融合';sendMessage()});\n  $$('.download-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();downloadResult(b.dataset.src)});\n}\nfunction addUser(text,baseLabel){const m=document.createElement('div');m.className='message user';const bubble=document.createElement('div');bubble.className='bubble';if(reference){const q=document.createElement('div');q.className='quote-inline';q.innerHTML=`<img src=\"${escapeHTML(resultImages.get(reference)||roomSrc)}\" alt=\"引用图\"><div><strong>引用效果图 ${escapeHTML(baseLabel)}</strong><span>作为本轮主编辑图</span></div>`;bubble.appendChild(q)}bubble.append(document.createTextNode((operation==='ADD'?'添加':'替换')+'：'+text));m.innerHTML='<div class=\"msgavatar\">你</div>';m.prepend(bubble);feedInner.appendChild(m)}\nfunction addAI(text){const m=document.createElement('div');m.className='message';m.innerHTML='<div class=\"msgavatar\">AI</div>';const b=document.createElement('div');b.className='bubble';b.textContent=text;m.appendChild(b);feedInner.appendChild(m)}\nfunction addProgress(){const box=document.createElement('div');box.className='round-status';box.innerHTML=['需求与空间解析','基础图片生成','尺寸、透视与接地修正','光影与场景融合','质量检查与可选纠错'].map((n,i)=>`<div class=\"round-row ${i===0?'running':''}\"><span class=\"round-dot\"></span><strong>${i===0?'分析':'阶段 '+i}</strong><span>${n}</span></div>`).join('');feedInner.appendChild(box);return box}\nfunction finishProgress(box,rounds,ok){const rows=$$('.round-row',box);rows.forEach(r=>r.className='round-row');rows.forEach((r,i)=>{if(i<Math.min(rows.length,rounds.length))r.classList.add('done')});if(!ok)rows[Math.min(rows.length-1,Math.max(0,rounds.length-1))].classList.add('failed')}\n\nfunction addResult(result,base){version++;const v='V'+version;resultImages.set(v,result.resultUrl);roomSrc=result.resultUrl;const qc=result.qc||{};const status=qc.pass?'QC PASS':'QC WARN';const d=getDimensions(),size=Object.values(d).some(Boolean)?Object.values(d).map(x=>x||'自动').join('×')+'cm':'模型自动估算';const wrap=document.createElement('div');wrap.className='asset-message';wrap.innerHTML=`<div class=\"image-card\"><div class=\"image-stage selectable-image effect-stage\" data-version=\"${v}\"><img class=\"room\" src=\"${escapeHTML(result.resultUrl)}\" alt=\"场景编辑效果图 ${v}\"></div><div class=\"image-caption\"><div class=\"image-caption-text\"><strong>效果图 ${v}</strong><span>基于 ${escapeHTML(base)} · ${size} · ${status} · ${result.attempts||1} 次生成</span></div><div class=\"image-actions\"><button class=\"image-action primary quote-btn\" data-version=\"${v}\">引用这张图</button><button class=\"image-action download-btn\" data-src=\"${escapeHTML(result.resultUrl)}\">下载</button><button class=\"image-action regen-btn\">重新生成</button></div></div></div>`;feedInner.appendChild(wrap);bindInteractive(wrap);return v}\nasync function downloadResult(src){if(!src)return;try{const r=await fetch(src);if(!r.ok)throw new Error('download');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='栖境AI-效果图.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{window.open(src,'_blank')}}\n\nfunction persistTasks(){try{localStorage.setItem(TASK_STORAGE_KEY,JSON.stringify(tasks.slice(0,20)))}catch(err){console.warn('任务记录保存失败',err)}}\nfunction loadTaskHistory(){try{const saved=JSON.parse(localStorage.getItem(TASK_STORAGE_KEY)||'[]');if(!Array.isArray(saved)||!saved.length)return;const live=new Map(tasks.map(t=>[t.id,t]));for(const item of saved)if(!live.has(item.id))live.set(item.id,item);tasks.splice(0,tasks.length,...[...live.values()].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,20));const nums=tasks.map(t=>Number(String(t.id).replace(/\\D/g,''))).filter(Number.isFinite);if(nums.length)taskCounter=Math.max(taskCounter,Math.max(...nums)+1)}catch(err){console.warn('任务记录读取失败',err)}}\nfunction newTask(text,base){const task={id:'TASK-'+taskCounter++,title:$('.chathead-title').textContent||deriveTitle(text),instruction:text,operation,base,target:{...target},dims:getDimensions(),status:'Running',rounds:[],createdAt:new Date().toISOString()};tasks.unshift(task);persistTasks();renderTaskRows();renderPipeline(task);return task}\nfunction renderTaskRows(){const root=$('#taskRows');root.innerHTML=tasks.map((t,index)=>{const images=(t.rounds||[]).filter(r=>r.imageUrl).length;return`<div class=\"task\" data-task-id=\"${t.id}\"><strong>${index===0?'<em class=\"latest\">最新</em> ':''}${t.id}</strong><span>${escapeHTML(t.title)}</span><span>${t.operation}</span><span>${escapeHTML(t.base)} · ${images} 张过程图</span><span class=\"status\">${escapeHTML(t.status)}</span><button class=\"view-flow\" data-id=\"${t.id}\">查看真实流程</button></div>`}).join('');$$('.view-flow',root).forEach(b=>b.onclick=()=>{const t=tasks.find(x=>x.id===b.dataset.id);if(t){renderPipeline(t);$('#pipeline').scrollIntoView({behavior:'smooth'})}})}\nfunction visualForRound(round){if(round.imageUrl)return`<div class=\"round-image-wrap\"><img class=\"round-room\" src=\"${escapeHTML(round.imageUrl)}\" alt=\"${escapeHTML(round.name)}实际输出图\"><a class=\"round-download\" href=\"${escapeHTML(round.imageUrl)}\" target=\"_blank\" rel=\"noopener\">查看 / 下载本轮</a></div>`;return`<div class=\"jsonbox\">${escapeHTML(JSON.stringify(round.data||{},null,2))}</div>`}\nfunction renderPipeline(task){const elapsed=task.elapsedMs?`${(task.elapsedMs/1000).toFixed(1)}s`:'执行中',imageCount=(task.rounds||[]).filter(r=>r.imageUrl).length;const cards=(task.rounds||[]).map((r,i)=>`<article class=\"round-card r${i}\"><div class=\"round-card-head\"><span class=\"round-name\">${escapeHTML(r.name||('Round '+i))}</span><span class=\"round-state\">${escapeHTML(r.state||'DONE')}${r.durationMs?` · ${(r.durationMs/1000).toFixed(1)}s`:''}</span></div><div class=\"round-visual\">${visualForRound(r)}</div><div class=\"round-body\"><p>${escapeHTML(r.description||'')}</p>${r.requestId?`<p class=\"request-id\"><strong>百炼 request_id</strong> ${escapeHTML(r.requestId)}</p>`:''}<div class=\"io-strip\"><span class=\"io\">输入<strong>${escapeHTML(r.input||'')}</strong></span><span class=\"io\">输出<strong>${escapeHTML(r.output||'')}</strong></span></div><details><summary>查看本轮 Prompt / 结果</summary><pre>${escapeHTML(r.prompt||JSON.stringify(r.data||{},null,2))}</pre></details></div></article>`).join('');$('#pipeline').innerHTML=`<div class=\"pipeline-head\"><div><h2>${task.id} · ${escapeHTML(task.title)}</h2><p>真实链路：需求解析 → 基础生成 → 几何修正 → 光影融合 → 质量检查${imageCount>3?' → 自动纠错':''}</p></div><div class=\"pipeline-summary\"><span class=\"summary-pill\">主编辑图 ${escapeHTML(task.base)}</span><span class=\"summary-pill\">落点 ${task.target.x}%, ${task.target.y}%</span><span class=\"summary-pill\">后台 ${imageCount} 张过程图</span><span class=\"summary-pill\">${elapsed}</span><span class=\"summary-pill\">${escapeHTML(task.status)}</span></div></div><div class=\"round-grid\">${cards||'<article class=\"round-card\"><div class=\"round-body\"><p>服务端正在执行。完成后会展示 3 张真实中间图；若质检失败，还会展示第 4 张纠错图。</p></div></article>'}</div>`}\n\nasync function asDataUrl(src){if(src.startsWith('data:'))return src;const r=await fetch(src);if(!r.ok)throw new Error('无法读取图片');const blob=await r.blob();return await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob)})}\nasync function resizeFile(file,maxSide=1536){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',.9))};img.src=reader.result};reader.readAsDataURL(file)})}\nfunction deriveTitle(text){return text.replace(/^(添加|替换)[:：]?/,'').slice(0,18)||'新的生图对话'}\nfunction currentSessionButton(){return $(`.session[data-chat=\"${currentChatId}\"]`)}\nfunction refreshHeader(){const messages=$$('.message',feedInner).length,images=$$('.effect-stage',feedInner).length;$('.chathead-meta').textContent=`已自动保存 · ${messages} 条消息 · ${images} 张真实生成图`;const b=currentSessionButton();if(b){const badge=$('.session-meta span:last-child',b);if(badge)badge.textContent=images?images+' 张图':'待生成'}}\n\nasync function sendMessage(){\n  const text=$('#prompt').value.trim();\n  if(!text)return toast('请先输入生图或调整要求');\n  if(!roomSrc)return toast('请先上传一张空间照片');\n  if(!productSrc)return toast('请先上传商品参考图');\n  if(!target)return toast('请先在空间照片上点选目标位置');\n  const btn=currentSessionButton();if(btn&&$('.session-title',btn).textContent==='新的生图对话'){const title=deriveTitle(text);$('.session-title',btn).textContent=title;$('.chathead-title').textContent=title}\n  const base=reference||'Original',baseImage=reference?(resultImages.get(reference)||roomSrc):roomSrc,task=newTask(text,base);\n  addUser(text,base);const progress=addProgress();$('#prompt').value='';$('#send').disabled=true;$('#replyBar').classList.remove('show');reference=null;feed.scrollTop=feed.scrollHeight;\n  const started=performance.now();\n  try{\n    const [roomImage,productImage]=await Promise.all([asDataUrl(baseImage),asDataUrl(productSrc)]);\n    const response=await fetch('/api/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({roomImage,productImage,instruction:text,operation,target,dimensions:getDimensions(),baseLabel:base})});\n    const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`生成服务返回 ${response.status}`);\n    task.rounds=payload.rounds||[];task.status=payload.qc?.pass?'Success':'Needs review';task.elapsedMs=Math.round(performance.now()-started);task.result={resultUrl:payload.resultUrl,qc:payload.qc,attempts:payload.attempts,models:payload.models,requestIds:payload.requestIds};persistTasks();renderTaskRows();renderPipeline(task);finishProgress(progress,task.rounds,!!payload.resultUrl);\n    const v=addResult(payload,base);const warnings=(payload.qc?.issues||[]).join('、');addAI(payload.qc?.pass?`已完成 ${v}。这是服务端场景编辑生成的单张融合图，不含前端商品叠加层；空间、透视、接地、光影和背景保护已通过视觉检查。`:`已完成 ${v}，但质量检查仍提示：${warnings||'建议补充更准确的尺寸或位置'}。系统已按规则自动重试一次。`);\n    refreshHeader();snapshotCurrent();toast(v+' 已生成，后台已同步真实轮次');\n  }catch(err){task.status='Failed';task.elapsedMs=Math.round(performance.now()-started);task.rounds.push({name:'错误',state:'FAILED',description:err.message,data:{message:err.message}});persistTasks();renderTaskRows();renderPipeline(task);finishProgress(progress,task.rounds,false);addAI('本次没有生成拼贴兜底图。场景编辑服务失败：'+err.message+'。已保留本轮素材与指令，可直接重新生成。');refreshHeader();snapshotCurrent();toast('生成失败：'+err.message)}\n  finally{$('#send').disabled=false;feed.scrollTop=feed.scrollHeight}\n}\n$('#send').onclick=sendMessage;$('#prompt').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')sendMessage()};\n\nfunction ensureInputImage(){if(!roomSrc||$('.selectable-image',feedInner))return;const wrap=document.createElement('div');wrap.className='asset-message';wrap.innerHTML=`<div class=\"asset-kicker\">本轮输入</div><div class=\"image-card\"><div class=\"image-stage selectable-image\" data-version=\"Original\"><img class=\"room\" src=\"${escapeHTML(roomSrc)}\" alt=\"用户上传的空间照片\"></div><div class=\"image-caption\"><div class=\"image-caption-text\"><strong>原始照片</strong><span>单击图片选择物体底部中心</span></div></div></div>`;feedInner.appendChild(wrap);bindInteractive(wrap)}\nfunction setTile(kind,src){const tile=$(kind==='room'?'#spaceTile':'#productTile'),img=$(kind==='room'?'#spaceThumb':'#productThumb');tile.classList.toggle('empty',!src);if(src)img.src=src;else img.removeAttribute('src')}\n$('#spaceInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{roomSrc=await resizeFile(f);setTile('room',roomSrc);feedInner.innerHTML='<div class=\"dayline\">新空间素材</div>';ensureInputImage();target=null;updateTargetUI();snapshotCurrent();toast('空间照片已更新，请点选目标位置')}catch{toast('空间照片读取失败，请更换清晰的 PNG 或 JPEG 图片')}finally{e.target.value=''}};\n$('#productInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;const status=$('#productStatus');status.textContent='正在优化商品参考图尺寸…';try{productSrc=await resizeFile(f);setTile('product',productSrc);status.className='product-status ok';status.textContent='商品原图已作为参考图保存 · 不会在浏览器直接抠图或叠加';snapshotCurrent();toast('商品参考图已更新')}catch{status.className='product-status error';status.textContent='商品图读取失败，请更换 PNG 或 JPEG 图片'}finally{e.target.value=''}};\n$('#attachProduct').onclick=()=>$('#productInput').click();\n\nfunction persistConversations(){try{localStorage.setItem(CONVERSATION_STORAGE_KEY,JSON.stringify({activeId:currentChatId,items:[...conversations.entries()].slice(0,12)}))}catch(err){console.warn('对话自动保存空间不足',err)}}\nfunction ensureSessionButton(id,state){if($(`.session[data-chat=\"${id}\"]`))return;const b=document.createElement('button');b.className='session';b.dataset.chat=id;b.innerHTML=`<div class=\"session-title\">${escapeHTML(state.title||'历史生图对话')}</div><div class=\"session-meta\"><span>已保存</span><span class=\"session-badge\">${escapeHTML((state.version||0)+' 张图')}</span></div>`;$('.searchbox').after(b);bindSession(b)}\nfunction loadConversations(){try{const saved=JSON.parse(localStorage.getItem(CONVERSATION_STORAGE_KEY)||'null');if(!saved||!Array.isArray(saved.items))return null;for(const [id,state] of saved.items){if(!id||!state)continue;conversations.set(id,state);ensureSessionButton(id,state)}return saved.activeId||null}catch(err){console.warn('对话记录读取失败',err);return null}}\nfunction snapshotCurrent(){if(!currentChatId)return;conversations.set(currentChatId,{title:$('.chathead-title').textContent,meta:$('.chathead-meta').textContent,feedHTML:feedInner.innerHTML,roomSrc,productSrc,version,target:target?{...target}:null,operation,reference,dimensions:getDimensions(),resultImages:Object.fromEntries(resultImages)});persistConversations()}\nfunction archivedState(title,count){return{title,meta:`已归档 · ${count} 张效果图`,feedHTML:`<div class=\"dayline\">已归档对话</div><div class=\"message\"><div class=\"msgavatar\">AI</div><div class=\"bubble\">此历史题目来自另一段独立对话；示例数据不冒充真实生成轮次。</div></div>`,roomSrc:'',productSrc:'',version:count,target:null,operation:title.includes('替换')?'REPLACE':'ADD',reference:null,dimensions:{}}}\nfunction restoreConversation(id){if(id===currentChatId)return;snapshotCurrent();currentChatId=id;const b=$(`.session[data-chat=\"${id}\"]`);let s=conversations.get(id);if(!s){const count=parseInt($('.session-meta span:last-child',b).textContent)||0;s=archivedState($('.session-title',b).textContent,count);conversations.set(id,s)}$('.chathead-title').textContent=s.title;$('.chathead-meta').textContent=s.meta;feedInner.innerHTML=s.feedHTML;roomSrc=s.roomSrc;productSrc=s.productSrc;version=s.version;target=s.target?{...s.target}:null;reference=s.reference;resultImages.clear();Object.entries(s.resultImages||{}).forEach(([key,value])=>resultImages.set(key,value));setOperation(s.operation,true);setTile('room',roomSrc);setTile('product',productSrc);const d=s.dimensions||{};$('#dimLength').value=d.length||'';$('#dimWidth').value=d.width||'';$('#dimHeight').value=d.height||'';$('#productStatus').textContent=productSrc?'商品原图仅作为外观参考 · 不再直接抠图叠加':'等待上传商品参考图';$('#replyBar').classList.toggle('show',!!reference);updateTargetUI();updateScaleHint();$$('.session').forEach(x=>x.classList.toggle('active',x.dataset.chat===id));bindInteractive(feedInner);persistConversations();toast('已恢复自动保存的独立对话')}\nfunction bindSession(b){b.onclick=()=>restoreConversation(b.dataset.chat)}\n$$('.session').forEach(bindSession);\nfunction startNewChat(){snapshotCurrent();const id='chat-'+Date.now(),b=document.createElement('button');b.className='session';b.dataset.chat=id;b.innerHTML='<div class=\"session-title\">新的生图对话</div><div class=\"session-meta\"><span>刚刚</span><span class=\"session-badge\">待生成</span></div>';$('.searchbox').after(b);bindSession(b);conversations.set(id,{title:'新的生图对话',meta:'独立对话 · 等待上传素材',feedHTML:'<div class=\"dayline\">新对话</div><div class=\"message\"><div class=\"msgavatar\">AI</div><div class=\"bubble\">这是一段全新的对话。上一段内容已经归档；请上传空间照片和商品参考图。</div></div>',roomSrc:'',productSrc:'',version:0,target:null,operation:'ADD',reference:null,dimensions:{},resultImages:{}});currentChatId='';restoreConversation(id);$('#prompt').value='';persistConversations();toast('新对话已清空，上一段已归档')}\n$('#newChat').onclick=startNewChat;$('#mobileNewChat').onclick=startNewChat;\n$('#sessionSearch').oninput=e=>$$('.session').forEach(s=>s.style.display=s.textContent.includes(e.target.value)?'':'none');\n$('#openContext').onclick=()=>innerWidth<=800?toast('素材面板在桌面宽度下显示'):$('#context').scrollIntoView({behavior:'smooth'});\n$('#refresh').onclick=()=>{loadTaskHistory();renderTaskRows();if(tasks[0])renderPipeline(tasks[0]);toast('已同步最新真实任务和各轮图片')};\n\nwindow.addEventListener('storage',e=>{if(e.key===TASK_STORAGE_KEY){loadTaskHistory();renderTaskRows();if(!admin.classList.contains('off')&&tasks[0])renderPipeline(tasks[0])}if(e.key===CONVERSATION_STORAGE_KEY&&document.visibilityState==='visible'){const savedId=loadConversations();if(savedId&&savedId!==currentChatId){currentChatId='';restoreConversation(savedId)}}});\nconst savedChatId=loadConversations();if(savedChatId&&conversations.has(savedChatId)){currentChatId='';restoreConversation(savedChatId)}else snapshotCurrent();loadTaskHistory();renderTaskRows();if(tasks[0])renderPipeline(tasks[0]);bindInteractive();updateTargetUI();updateScaleHint();\n";
const ROOM_BYTES = "";
const PRODUCT_BYTES = "";

const JSON_HEADERS={"content-type":"application/json; charset=utf-8","cache-control":"no-store"};
const EDIT_SYSTEM=`You are a production-grade scene-aware interior image editor, not a compositor.
Perform localized image editing / inpainting around the requested placement region. Re-render the inserted object as part of the photographed 3D scene.
Hard constraints:
- preserve room structure, camera angle, lens perspective, vanishing directions and framing;
- preserve all unedited walls, floors, ceilings, doors, windows, fixtures and objects;
- match the product reference's shape, color, material, construction and distinctive design details;
- insert the furniture naturally at the requested normalized position and orientation;
- use realistic physical scale from supplied dimensions; otherwise infer category-appropriate scale from the floor plane, depth and nearby references;
- align the object to the supporting floor, wall, tabletop or shelf; no floating, sinking or wall penetration;
- match perspective foreshortening, occlusion ordering, ambient light direction, exposure and color temperature;
- create physically plausible contact shadows, soft cast shadows and subtle bounced light;
- output one photorealistic interior photograph, not a collage, sticker, cutout, mockup, product-page overlay or transparent layer;
- do not copy product-page text, price tags, UI, background, watermark or surrounding props into the room.
Change only what the instruction requires.`;

const ROUND_PROMPTS={
  base:`你是一个真实家居空间图片编辑模型。根据基础房间图片、家具商品参考图、结构化任务和用户要求完成第一次图片编辑。保持基础图片的空间结构、拍摄角度、构图和透视关系；仅修改指定对象或区域；严格参考商品外形、颜色、材质、结构和关键设计细节。ADD 不删除原有家具，REPLACE 只替换指定家具。根据透视和尺寸调整大小与角度，使商品与支撑面自然接触。输出真实室内摄影预览，不要重新设计整个房间。优先级：完成用户要求 > 商品保真 > 空间保真 > 视觉自然。`,
  geometry:`检查上一轮效果图中的空间与几何关系，只修正必要问题：家具尺寸、透视、接地、悬空、穿模、结构扭曲、前后遮挡和用户指定位置。除非为修复这些问题，不得重新设计商品或修改房间背景；不得改变房间布局、门窗、墙地面、未编辑家具及商品设计特征。目标是提高空间真实性，不是生成新的装修方案。`,
  lighting:`在不改变商品位置、尺寸、结构和房间布局的情况下，提高商品与真实房间的视觉融合。仅优化光照方向与强度、色温、接触阴影与投影、环境反射、色彩一致性、必要的清晰度与边缘融合。不得增加家具或装饰，不得改变未指定区域，不得重新设计商品。最终图应像商品真实放在原房间中拍摄。`,
  retry:`根据质量检查指出的问题，对上一轮结果做一次局部纠错。只处理明确失败项，保持已经正确的商品外观、位置、房间结构和未编辑区域。不得借机重做房间或改变商品款式。`
};

function corsHeaders(request){const origin=request.headers.get('origin')||'*';return{"access-control-allow-origin":origin,"access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"content-type","vary":"origin"}}
function json(data,status=200,request){return new Response(JSON.stringify(data),{status,headers:{...JSON_HEADERS,...corsHeaders(request)}})}
function assetResponse(base64,type){const raw=atob(base64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Response(bytes,{headers:{"content-type":type,"cache-control":"public, max-age=86400"}})}
function assertDataImage(value,name){if(typeof value!=='string'||!/^data:image\/(png|jpeg|webp);base64,/i.test(value))throw new Error(`${name} 必须是 PNG/JPEG/WebP 图片`);if(value.length>14_000_000)throw new Error(`${name} 超过 10MB，请压缩后重试`)}
function parseModelJSON(text,fallback){if(!text)return fallback;try{return JSON.parse(text)}catch{}const match=String(text).match(/\{[\s\S]*\}/);if(match){try{return JSON.parse(match[0])}catch{}}return{...fallback,raw:String(text).slice(0,3000)}}
function textFromChat(data){const content=data?.choices?.[0]?.message?.content;if(typeof content==='string')return content;if(Array.isArray(content))return content.map(x=>x.text||'').join('\n');return''}
function imageUrlFromResponse(data){return data?.data?.[0]?.url||data?.output?.choices?.[0]?.message?.content?.find?.(x=>x.image)?.image||data?.output?.results?.[0]?.url||null}

function dashRoot(env){
  return (env.DASHSCOPE_BASE_URL||'https://dashscope.aliyuncs.com').replace(/\/compatible-mode\/v1\/?$/,'').replace(/\/$/,'');
}

async function dashFetch(env,path,body){
  if(!env.DASHSCOPE_API_KEY)throw new Error('服务端缺少 DASHSCOPE_API_KEY');
  const endpoint=dashRoot(env)+path;
  const response=await fetch(endpoint,{method:'POST',headers:{authorization:`Bearer ${env.DASHSCOPE_API_KEY}`,'content-type':'application/json'},body:JSON.stringify(body)});
  const data=await response.json().catch(()=>({}));
  const requestId=response.headers.get('x-request-id')||data?.request_id||data?.output?.request_id||null;
  if(!response.ok){
    const reason=data?.error?.message||data?.message||data?.code||`HTTP ${response.status}`;
    throw new Error(`百炼接口 ${response.status}：${reason}${requestId?`（request_id: ${requestId}）`:''}`);
  }
  return{data,requestId,endpoint};
}

async function analyzeScene(env,input){
  const dims=input.dimensions||{},sizeText=dims.length||dims.width||dims.height?`Known real dimensions in cm: L=${dims.length||'unknown'}, W=${dims.width||'unknown'}, H=${dims.height||'unknown'}. Treat supplied values as hard constraints.`:'No dimensions supplied. Infer a conservative category-appropriate size from scene depth and nearby architectural references.';
  const requestText=`Analyze the base scene for a localized furniture edit. Target point is normalized image coordinate x=${input.target.x}%, y=${input.target.y}% and denotes the bottom-center contact point. Operation=${input.operation}. User instruction: ${input.instruction}. ${sizeText}
Return JSON only with: scene_type, support_surface, floor_or_surface_polygon, horizon_y_percent, vanishing_direction, camera_view, depth_at_target, light_direction, light_softness, color_temperature, nearby_scale_references, obstacles, occlusion_rules, recommended_orientation, estimated_dimensions_cm, placement_safety, warnings. Do not redesign the room.`;
  const response=await dashFetch(env,'/compatible-mode/v1/chat/completions',{model:env.VISION_MODEL||'qwen3-vl-plus',temperature:0.1,response_format:{type:'json_object'},messages:[{role:'system',content:'You are a geometric scene analyst for photorealistic localized image editing. Return strict JSON.'},{role:'user',content:[{type:'image_url',image_url:{url:input.roomImage}},{type:'text',text:requestText}]}]});
  return{analysis:parseModelJSON(textFromChat(response.data),{support_surface:'unknown',depth_at_target:'unknown',placement_safety:'review',warnings:['scene analysis JSON parse fallback']}),requestId:response.requestId};
}

function taskContext(input,analysis){
  const d=input.dimensions||{},dimensionText=d.length||d.width||d.height?`Use real dimensions exactly as constraints: length ${d.length||'unspecified'} cm, width ${d.width||'unspecified'} cm, height ${d.height||'unspecified'} cm.`:`No dimensions were supplied. Use the scene analysis and common product-category dimensions; prefer a believable conservative scale over an oversized object.`;
  return `操作类型：${input.operation}\n用户要求：${input.instruction}\n目标落点为图像归一化坐标 x=${input.target.x}%, y=${input.target.y}%，表示物体底部中心接触点。${dimensionText}\n场景分析 JSON：${JSON.stringify(analysis)}`;
}

function buildStagePrompt(stage,input,analysis,correction=''){
  const imageRoles=stage==='base'?'Image 1 是不可变的基础房间图和主编辑画布；Image 2 是商品外观参考。':'Image 1 是上一轮中间结果和本轮主编辑画布；Image 2 是商品外观参考；Image 3 是原始基础房间图，仅用于锁定未编辑背景、结构、机位和构图。';
  return `${EDIT_SYSTEM}\n\n${imageRoles}\n\n${ROUND_PROMPTS[stage]}\n\n结构化上下文\n${taskContext(input,analysis)}${correction?`\n\n质量检查纠错要求\n${correction}`:''}`;
}

async function generateStage(env,stage,input,analysis,previousUrl=null,correction=''){
  const content=stage==='base'?[{image:input.roomImage},{image:input.productImage}]:[{image:previousUrl},{image:input.productImage},{image:input.roomImage}];
  const prompt=buildStagePrompt(stage,input,analysis,correction);content.push({text:prompt});
  const response=await dashFetch(env,'/api/v1/services/aigc/multimodal-generation/generation',{model:env.IMAGE_EDIT_MODEL||'qwen-image-3.0',input:{messages:[{role:'user',content}]},parameters:{size:'1536*1024',n:1,prompt_extend:true,watermark:false}});
  const url=imageUrlFromResponse(response.data);if(!url)throw new Error(`图像编辑模型未返回图片地址${response.requestId?`（request_id: ${response.requestId}）`:''}`);return{url,requestId:response.requestId,prompt};
}

async function inspectQuality(env,input,analysis,resultUrl){
  const prompt=`你是家居 AI 图片质量检查助手。比较基础房间图、商品参考图、最终生成图、用户要求和结构化任务。目标底部中心为 x=${input.target.x}%, y=${input.target.y}%。场景分析：${JSON.stringify(analysis)}。
Return strict JSON with: pass(boolean), overall_score(0-100), collage_artifact_score(0-100 where 100 is fully natural), scale_score, perspective_score, grounding_score, shadow_lighting_score, product_similarity_score, background_preservation_score, floating(boolean), severe_occlusion_error(boolean), background_damage(boolean), issues(array of short Chinese strings), correction_prompt(string).
检查用户要求、商品一致性、位置、比例、透视、悬空/穿模/结构异常、背景误改和光影。若无明显问题输出 PASS；若有明显问题输出 FAIL，并指出最需修正的 1–3 项。不要因为轻微审美差异判定失败。`;
  const response=await dashFetch(env,'/compatible-mode/v1/chat/completions',{model:env.VISION_MODEL||'qwen3-vl-plus',temperature:0.1,response_format:{type:'json_object'},messages:[{role:'system',content:'You are a strict visual QA inspector for scene-aware image editing. Return JSON only.'},{role:'user',content:[{type:'image_url',image_url:{url:input.roomImage}},{type:'image_url',image_url:{url:input.productImage}},{type:'image_url',image_url:{url:resultUrl}},{type:'text',text:prompt}]}]});
  const qc=parseModelJSON(textFromChat(response.data),{pass:false,overall_score:0,issues:['QC 响应无法解析'],correction_prompt:'Rebuild the object as part of the scene and preserve the base room.'});qc.pass=qc.pass===true;return{qc,requestId:response.requestId};
}

async function runPipeline(env,input){
  const rounds=[];
  let started=Date.now();
  const analysisResponse=await analyzeScene(env,input),analysis=analysisResponse.analysis;
  rounds.push({name:'Round 0 需求解析',state:'ANALYZED',description:'把用户输入转为结构化任务，并识别支撑面、纵深、透视、光线、遮挡与尺度参照。',input:'基础图 + 商品图 + 用户指令 + 点选位置 + 尺寸',output:'scene-analysis.json',requestId:analysisResponse.requestId,durationMs:Date.now()-started,data:{request_id:analysisResponse.requestId,...analysis},prompt:'PRD Round 0：需求解析与空间理解；本轮不生成图片。'});

  started=Date.now();let editResponse=await generateStage(env,'base',input,analysis),resultUrl=editResponse.url;
  rounds.push({name:'Round 1 基础生成',state:'GENERATED',description:'完成 ADD / REPLACE，优先确保用户要求、商品外观和空间结构正确。',input:'原始基础图 + 商品参考图 + 结构化任务',output:'round-1-base.png',requestId:editResponse.requestId,durationMs:Date.now()-started,imageUrl:resultUrl,prompt:editResponse.prompt});

  started=Date.now();editResponse=await generateStage(env,'geometry',input,analysis,resultUrl);resultUrl=editResponse.url;
  rounds.push({name:'Round 2 几何修正',state:'GENERATED',description:'基于上一轮真实图片，修正尺寸、透视、接地、遮挡、悬空和穿模。',input:'Round 1 图 + 商品参考图 + 原始背景锁定图',output:'round-2-geometry.png',requestId:editResponse.requestId,durationMs:Date.now()-started,imageUrl:resultUrl,prompt:editResponse.prompt});

  started=Date.now();editResponse=await generateStage(env,'lighting',input,analysis,resultUrl);resultUrl=editResponse.url;
  rounds.push({name:'Round 3 光影融合',state:'GENERATED',description:'基于几何修正图，只优化接触阴影、色温、环境光、反射和边缘融合。',input:'Round 2 图 + 商品参考图 + 原始背景锁定图',output:'round-3-lighting.png',requestId:editResponse.requestId,durationMs:Date.now()-started,imageUrl:resultUrl,prompt:editResponse.prompt});

  started=Date.now();let qcResponse=await inspectQuality(env,input,analysis,resultUrl),qc=qcResponse.qc;
  rounds.push({name:'Round 4 质量检查',state:qc.pass?'PASS':'RETRY',description:'比较基础图、商品图、用户要求和最终图，检查商品、位置、比例、透视、接地、背景与光影。',input:'原始图 + 商品图 + Round 3 图',output:'qc-final.json',requestId:qcResponse.requestId,durationMs:Date.now()-started,data:{request_id:qcResponse.requestId,...qc},prompt:'PRD Round 4：最终质量检查；只输出 PASS / FAIL 与最需修正的问题。'});
  let attempts=3;
  if(!qc.pass){
    attempts=4;const correction=qc.correction_prompt||`修正：${(qc.issues||[]).join('；')}`;
    started=Date.now();editResponse=await generateStage(env,'retry',input,analysis,resultUrl,correction);resultUrl=editResponse.url;
    rounds.push({name:'Round 5 自动纠错图',state:'GENERATED',description:'质量检查未通过，基于 Round 3 仅修复明确失败项；这是最多一次的自动纠错。',input:'Round 3 图 + 商品参考图 + 原始背景锁定图 + QC',output:'round-4-retry.png',requestId:editResponse.requestId,durationMs:Date.now()-started,imageUrl:resultUrl,prompt:editResponse.prompt});
    started=Date.now();qcResponse=await inspectQuality(env,input,analysis,resultUrl);qc=qcResponse.qc;
    rounds.push({name:'Round 6 纠错后质检',state:qc.pass?'PASS':'NEEDS_REVIEW',description:'对第 4 张后台生成图执行最终复检，不再继续自动生成。',input:'原始图 + 商品图 + 纠错图',output:'qc-retry.json',requestId:qcResponse.requestId,durationMs:Date.now()-started,data:{request_id:qcResponse.requestId,...qc},prompt:'最终复检：输出 PASS / FAIL 与遗留问题。'});
  }
  return{resultUrl,analysis,qc,attempts,rounds,requestIds:rounds.map(r=>r.requestId).filter(Boolean),models:{analysis:env.VISION_MODEL||'qwen3-vl-plus',editing:env.IMAGE_EDIT_MODEL||'qwen-image-3.0',quality:env.VISION_MODEL||'qwen3-vl-plus'}};
}

export default{
  async fetch(request,env){
    const url=new URL(request.url);
    if(request.method==='OPTIONS')return new Response(null,{status:204,headers:corsHeaders(request)});
    if(url.pathname==='/')return new Response(PAGE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-cache'}});
    if(url.pathname==='/app.js')return new Response(APP_JS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-cache'}});
    if(url.pathname==='/assets/living-room.png')return assetResponse(ROOM_BYTES,'image/png');
    if(url.pathname==='/assets/caramel-chair.png')return assetResponse(PRODUCT_BYTES,'image/png');
    if(url.pathname==='/api/health')return json({ok:true,configured:!!env.DASHSCOPE_API_KEY,mode:'scene-aware-editing',endpointFamily:'dashscope-native-image-edit',models:{vision:env.VISION_MODEL||'qwen3-vl-plus',image:env.IMAGE_EDIT_MODEL||'qwen-image-3.0'}},200,request);
    if(url.pathname==='/api/generate'&&request.method==='POST'){
      try{const input=await request.json();assertDataImage(input.roomImage,'空间图');assertDataImage(input.productImage,'商品图');if(!input.target||!Number.isFinite(input.target.x)||!Number.isFinite(input.target.y))throw new Error('缺少有效点选位置');input.operation=input.operation==='REPLACE'?'REPLACE':'ADD';input.instruction=String(input.instruction||'').slice(0,1600);if(!input.instruction)throw new Error('缺少生图指令');return json(await runPipeline(env,input),200,request)}catch(error){return json({error:error?.message||'生成失败'},500,request)}
    }
    return new Response('Not found',{status:404});
  }
};
